def minPath(grid, k):
    n = len(grid)
    # locate the cell containing value 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                x, y = i, j
    # find the smallest value among neighbors of the cell containing 1
    val = n * n + 1
    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        ni, nj = x + dx, y + dy
        if 0 <= ni < n and 0 <= nj < n:
            val = min(val, grid[ni][nj])
    # optimal path alternates: 1, val, 1, val, ...
    ans = []
    for i in range(k):
        if i % 2 == 0:
            ans.append(1)
        else:
            ans.append(val)
    return ans
```

